from langsmith import traceable

client = openai.Client()

@traceable(run_type="llm", name="Minimal Trace", project_name="My Project")
def call_openai(msgs):
    return client.chat.completions.create(
        model="gpt-4o-mini",
        messages=msgs,
    ).choices[0].message.content

